import {enhanceFilters} from './filter-menu.js';
import {loadCatalog,filterStructures,studyCards,factVariants} from './data.js';
import {makeRun} from './logic.js';
const app=document.querySelector('#knowledge-app');
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={catalog:null,models:[],filters:{modelId:'',query:'',types:'',systems:'',regions:'',organs:'',tags:'',images:false},results:[],selected:null,page:0,imageIndex:0,view:'browse',studyScope:[],mode:'knowledge',topic:'',order:'random',run:[],position:0,revealed:false};
const btn=(text,action,extra='',cls='secondary')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const count=n=>n.toLocaleString();
const getStructure=()=>state.catalog.byId.get(state.selected);
const modelName=id=>state.models.find(m=>m.id===id)?.name||id;
const variantsCount=s=>s.facts.filter(f=>!f.preferredVariantId&&f.variants.length>1).length;
const options=(values,selected,label)=>`<option value="">${label}</option>${values.map(v=>`<option value="${e(v)}" ${selected===v?'selected':''}>${e(v)}</option>`).join('')}`;
function selectControl(key,label){const values=[...new Set(state.catalog.structures.filter(s=>s.kind!=='model-note').flatMap(s=>s[key]))].sort();return `<label>${label}<select data-filter="${key}">${options(values,state.filters[key],({types:'All types',systems:'All systems',regions:'All regions',organs:'All organ collections',tags:'All tags'})[key])}</select></label>`;}
function browse(){app.innerHTML=`<section class="knowledge-heading"><div><div class="eyebrow">Beyond the lab</div><h1>Anatomy library</h1><p>Explore structures, connect what you know, and build a revision run.</p></div><span class="library-total">${count(state.catalog.structures.filter(s=>s.kind!=='model-note').length)} structures · ${state.models.length} models</span></section><section class="knowledge-filters" aria-label="Library filters"><label class="knowledge-search">Search the library<input type="search" id="knowledge-search" value="${e(state.filters.query)}" placeholder="Structure, label number (e.g. 27a), or fact…" autocomplete="off"></label><div class="facet-grid"><label>Model<select data-filter="modelId"><option value="">All models</option>${state.models.map(m=>`<option value="${e(m.id)}" ${state.filters.modelId===m.id?'selected':''}>${e(m.name)}</option>`).join('')}</select></label>${selectControl('types','Structure type')}${selectControl('systems','System')}${selectControl('regions','Region')}${selectControl('organs','Organ collection')}${selectControl('tags','Tag')}</div><div class="filter-footer"><label class="check-label"><input type="checkbox" data-filter="images" ${state.filters.images?'checked':''}> With a structure image</label>${btn('Clear filters','clear','','text-button')}</div></section><div class="knowledge-results-bar"><p id="result-summary" role="status"></p>${btn('Revise results','revise-results','','primary')}</div><div class="knowledge-layout"><section class="knowledge-list-panel" aria-label="Matching structures"><div id="knowledge-list"></div><div id="knowledge-pagination" class="pagination"></div></section><section id="structure-detail" aria-label="Structure details"></section></div>`;refreshResults();enhanceFilters(app.querySelector('.knowledge-filters'));}
function refreshResults(){state.results=filterStructures(state.catalog.structures,state.filters);if(!state.results.some(s=>s.id===state.selected)){state.selected=state.results[0]?.id||null;state.imageIndex=0;}state.page=Math.min(state.page,Math.max(0,Math.ceil(state.results.length/30)-1));app.querySelector('#result-summary').textContent=`${count(state.results.length)} matching structures`;app.querySelector('[data-action="revise-results"]').disabled=!state.results.length;
app.querySelector('#knowledge-list').innerHTML=state.results.slice(state.page*30,state.page*30+30).map(s=>`<button class="structure-result" data-action="structure" data-id="${s.id}" aria-pressed="${s.id===state.selected}"><span class="structure-result-name">${e(s.name)}</span><span>${e(s.types.join(' · '))}${s.scope?' · '+e(s.regions.join(', ')):''}</span><small>${s.facts.filter(f=>f.question!=='Identification').length} topics · ${new Set(s.occurrences.map(o=>o.modelId)).size} models${s.imageIds.length?' · Image available':''}</small>${state.filters.modelId||/^#?(?:label\s*)?\d+[a-z]?$/i.test(state.filters.query.trim())?`<small>${s.occurrences.filter(o=>(!state.filters.modelId||o.modelId===state.filters.modelId)&&(!/^#?(?:label\s*)?\d+[a-z]?$/i.test(state.filters.query.trim())||String(o.label).toLowerCase()===state.filters.query.toLowerCase().trim().replace(/^#|^label\s*/g,''))).map(o=>e(modelName(o.modelId)+' · Label '+o.label+(o.section?' · '+o.section:''))).join('<br>')}</small>`:''}</button>`).join('')||'<div class="empty"><h2>No matching structures</h2><p>Try a broader search or clear a filter.</p></div>';
app.querySelector('#knowledge-pagination').innerHTML=state.results.length>30?`${btn('Previous','page-prev',state.page?'':'disabled')}<span>${state.page+1} / ${Math.ceil(state.results.length/30)}</span>${btn('Next','page-next',(state.page+1)*30<state.results.length?'':'disabled')}`:'';renderDetail();}
function credit(im){return im.credit?`<figcaption>${e(im.credit)}${im.license?' · '+e(im.license):''}${im.sourceUrl&&/^https?:\/\//.test(im.sourceUrl)?` · <a href="${e(im.sourceUrl)}" target="_blank" rel="noopener noreferrer">Source</a>`:''}</figcaption>`:'';}
function imageMarkup(s){const ims=s.imageIds.map(id=>state.catalog.imagesById.get(id)).filter(Boolean);if(!ims.length)return '<div class="image-unavailable"><span aria-hidden="true">▧</span><div><strong>No structure image yet</strong><p>You can still explore the facts and practise knowledge questions.</p></div></div>';const im=ims[state.imageIndex%ims.length];return `<figure class="structure-figure"><img src="./${e(im.src)}" alt="${e(im.alt)}" decoding="async"><div class="image-failure" role="status" hidden>This image is unavailable.</div>${im.modelId?`<p class="image-model">${e(modelName(im.modelId))}</p>`:''}${im.caption?`<p>${e(im.caption)}</p>`:''}${credit(im)}</figure>${ims.length>1?`<div class="image-navigation">${btn('Previous image','image-prev')}<span>${state.imageIndex%ims.length+1} / ${ims.length}</span>${btn('Next image','image-next')}</div>`:''}`;}
function sourcesMarkup(sources){const seen=new Set();return sources.filter(s=>{const key=s.modelId+':'+s.cardId;if(seen.has(key))return false;seen.add(key);return true;}).map(s=>`<a href="./?model=${encodeURIComponent(s.modelId)}">${e(modelName(s.modelId))}</a>`).join(' · ');}
function renderDetail(force=false){const host=app.querySelector('#structure-detail'),s=getStructure();if(!s){delete host.dataset.structureId;host.innerHTML='<div class="empty">Choose a structure to explore its anatomy.</div>';return;}
const previous=host.dataset.structureId;if(previous===s.id&&!force)return;host.dataset.structureId=s.id;
const facts=s.facts.filter(f=>f.question!=='Identification');host.innerHTML=`<article class="structure-sheet"><div class="detail-heading"><div><div class="eyebrow">${e(s.types.join(' · '))}</div><h2 tabindex="-1">${e(s.name)}</h2>${s.aliases.length?`<p class="aliases">Also listed as ${s.aliases.map(e).join(', ')}</p>`:''}</div>${btn('Revise this','revise-one','','primary')}</div><div class="detail-tags">${[...s.regions,...s.systems].map(t=>`<span>${e(t)}</span>`).join('')}</div>${imageMarkup(s)}${variantsCount(s)?`<p class="source-note">Some topics have different answers in the source guides. Each version is shown with its source.</p>`:''}<div class="fact-list">${facts.map(f=>{const vs=factVariants(f);return `<section class="fact"><h3>${e(f.question)}${vs.length>1?`<span>${vs.length} source versions</span>`:''}</h3>${vs.map(v=>`<div class="fact-version"><p>${e(v.answer)}</p><details><summary>Source${v.sources.length===1?'':'s'}</summary><div class="source-links">${sourcesMarkup(v.sources)}</div></details></div>`).join('')}</section>`}).join('')||'<p class="empty">This entry currently contains identification information only.</p>'}</div><details class="model-references"><summary>Find on a model · ${s.occurrences.length} labels</summary><ul>${s.occurrences.map(o=>`<li><a href="./?model=${encodeURIComponent(o.modelId)}">${e(modelName(o.modelId))}</a><span>${e(o.section)}${o.section?' · ':''}Label ${e(o.label)}</span></li>`).join('')}</ul></details><details class="collection-note"><summary>About these collections</summary><p>Initial collections use the existing structure tags and the models where each structure appears. A structure may belong to several collections. Reviewed synonyms share one record; distinct anatomical structures remain separate.</p></details></article>`;
if(previous!==s.id)host.scrollTop=0;
}
function openStudy(structures){state.studyScope=structures;state.view='setup';state.topic='';state.mode='knowledge';drawStudySetup();window.scrollTo(0,0);}
function pendingCards(){return studyCards(state.studyScope,state.catalog,{mode:state.mode,topic:state.topic});}
function drawStudySetup(){const n=pendingCards().length;const images=studyCards(state.studyScope,state.catalog,{mode:'identification'}).length;const topics=[...new Set(state.studyScope.flatMap(s=>s.facts.map(f=>f.question)).filter(q=>q!=='Identification'))].sort();app.innerHTML=`<section class="session library-study"><div>${btn('← Back to library','back','','text-button')}</div><div class="eyebrow">Your next run</div><h1>Revise ${state.studyScope.length===1?e(state.studyScope[0].name):count(state.studyScope.length)+' structures'}</h1><p>Work through the selected anatomy once, in your chosen order.</p><div class="panel"><fieldset><legend>Revision mode</legend><div class="study-modes"><label><input type="radio" name="mode" value="knowledge" ${state.mode==='knowledge'?'checked':''}><span><strong>Knowledge questions</strong><small>Recall facts from a structure’s name. No image needed.</small></span></label><label><input type="radio" name="mode" value="identification" ${state.mode==='identification'?'checked':''} ${images?'':'disabled'}><span><strong>Image identification</strong><small>${images} structures with a quiz-ready image.</small></span></label></div></fieldset><div class="study-settings"><label>Topic<select id="study-topic" ${state.mode==='identification'?'disabled':''}>${options(topics,state.topic,'All topics')}</select></label><label>Order<select id="study-order"><option value="random" ${state.order==='random'?'selected':''}>Random</option><option value="sequential" ${state.order==='sequential'?'selected':''}>In order</option></select></label></div></div><div class="start-row"><div><strong>${count(n)} cards</strong><p>${n?'Duplicate copies of the same fact are included once.':'No cards available for this selection.'}</p></div>${btn('Start revision','start',n?'':'disabled','primary')}</div><p class="study-note">Each topic uses one shared revision answer across models. Every run starts fresh.</p></section>`;}
function drawRun(){const c=state.run[state.position];if(!c){state.view='done';app.innerHTML=`<section class="session"><div class="panel complete"><div class="complete-mark" aria-hidden="true">✓</div><h1>Run complete</h1><p>You covered ${state.run.length} cards.</p>${btn('Start a fresh run','start','','primary')} ${btn('Back to library','back')}</div></section>`;return;}
const im=c.image;const marker=im?.quizMarker;app.innerHTML=`<section class="session library-study"><div class="session-top">${btn('← End run','back','','text-button')}<span class="session-count">${state.position+1} / ${state.run.length}</span></div><progress value="${state.position}" max="${state.run.length}" aria-label="Cards passed"></progress><article class="flashcard" tabindex="-1"><div class="card-meta"><span>${c.identification?'Image identification':'Knowledge question'}</span><span>${e(c.question)}</span></div>${c.identification?`<figure class="quiz-figure"><div class="marked-image"><img src="./${e(state.revealed&&im.answerSrc?im.answerSrc:im.quizSrc)}" alt="${e(state.revealed?im.alt:im.quizAlt)}"><div class="image-failure" role="status" hidden>Image unavailable. Return to the library to choose another run.</div>${marker&&!(state.revealed&&im.answerSrc)?`<span class="image-marker" style="left:${marker.x*100}%;top:${marker.y*100}%" aria-hidden="true">A</span>`:''}</div>${state.revealed?credit(im):''}</figure>`:`<h1 class="knowledge-prompt">${e(c.name)}</h1>`}<h2 class="question">${e(c.question)}</h2>${(c.variantCount>1||/model/i.test(c.question))?`<p class="source-note">${c.variantCount>1?'One of '+c.variantCount+' source versions':'Model-specific question'} · ${e([...new Set(c.sources.map(s=>modelName(s.modelId)))].join(' · '))}</p>`:''}${state.revealed?`<div class="answer" role="status">${e(c.answer)}</div>`:btn('Reveal answer','reveal','','primary reveal')}</article><div class="session-controls">${btn('← Previous','previous',state.position?'':'disabled')}${btn(state.position===state.run.length-1?'Finish run':'Next card →','next',state.revealed?'':'disabled','primary')}</div><p class="shortcuts">Space to reveal · ← previous · → next after revealing</p></section>`;app.querySelector('.flashcard').focus({preventScroll:true});}
function action(name,id){
 if(name==='structure'){state.selected=id;state.imageIndex=0;app.querySelectorAll('.structure-result').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===id)));renderDetail();if(innerWidth<850){app.querySelector('#structure-detail').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}app.querySelector('.detail-heading h2').focus({preventScroll:true});return;}
 if(name==='clear'){state.filters={modelId:'',query:'',types:'',systems:'',regions:'',organs:'',tags:'',images:false};state.page=0;browse();return;}
 if(name==='page-prev'||name==='page-next'){state.page+=name==='page-prev'?-1:1;refreshResults();app.querySelector('#knowledge-list').scrollTop=0;return;}
 if(name==='image-prev'||name==='image-next'){const n=getStructure().imageIds.length;state.imageIndex=(state.imageIndex+(name==='image-next'?1:-1)+n)%n;renderDetail(true);return;}
 if(name==='revise-results'){openStudy(state.results);return;}if(name==='revise-one'){openStudy([getStructure()]);return;}
 if(name==='back'){state.view='browse';state.run=[];browse();return;}
 if(name==='start'){const cards=pendingCards();if(!cards.length)return;state.run=makeRun(cards,state.order==='random');state.position=0;state.revealed=false;state.view='run';drawRun();return;}
 if(state.view!=='run')return;
 if(name==='reveal')state.revealed=true;
 if(name==='previous'&&state.position>0){state.position--;state.revealed=false;}
 if(name==='next'&&state.revealed){state.position++;state.revealed=false;}
 drawRun();
}
app.addEventListener('click',event=>{const b=event.target.closest('button[data-action]');if(b&&!b.disabled)action(b.dataset.action,b.dataset.id);});
app.addEventListener('input',event=>{if(event.target.id==='knowledge-search'){state.filters.query=event.target.value;state.page=0;refreshResults();}});
app.addEventListener('change',event=>{const el=event.target;if(el.dataset.filter){state.filters[el.dataset.filter]=el.type==='checkbox'?el.checked:el.value;state.page=0;refreshResults();}if(el.name==='mode'){state.mode=el.value;drawStudySetup();}if(el.id==='study-topic'){state.topic=el.value;drawStudySetup();}if(el.id==='study-order')state.order=el.value;});
app.addEventListener('error',event=>{if(event.target.tagName==='IMG'){event.target.hidden=true;const message=event.target.parentElement.querySelector('.image-failure');if(message)message.hidden=false;}},true);
document.addEventListener('keydown',event=>{if(state.view!=='run'||event.repeat||event.ctrlKey||event.metaKey||event.altKey||event.target.closest('input,select,textarea,[contenteditable=true]'))return;if(event.code==='Space'){event.preventDefault();if(!state.revealed)action('reveal');}if(event.key==='ArrowRight'){event.preventDefault();action('next');}if(event.key==='ArrowLeft'){event.preventDefault();action('previous');}});
try{const [catalog,response]=await Promise.all([loadCatalog(),fetch('./data/models.json')]);if(!response.ok)throw Error('Model index unavailable');state.catalog=catalog;state.models=await response.json();const requested=new URLSearchParams(location.search).get('structure');if(catalog.byId.has(requested)){state.selected=catalog.byId.get(requested).id;state.filters.query=catalog.byId.get(requested).name;}browse();}catch(error){app.innerHTML='<section class="error"><h1>The library could not be loaded</h1><p>Check your connection and reload the page.</p><button class="secondary" onclick="location.reload()">Reload</button></section>';}
if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'read_anatomy_library_selection',description:'Read the current anatomy library filters, result count and selected structure.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({filters:state.filters,resultCount:state.results.length,selected:getStructure()?.name,view:state.view})});}catch{}}

if(['localhost','127.0.0.1'].includes(location.hostname)){const link=document.createElement('a');link.href='./manage-images';link.textContent='Add images';document.querySelector('.site-nav').append(link);}
